// 计算偶数和
func evenSum(from, to int, ch chan int) {
  result := 0
  for i:=from; i<=to; i++ {
    if i%2 == 0 {
      result += i
    }    
  }
  ch <- result
}
// 计算平方和
func squareSum(from, to int, ch chan int) {
  result := 0
  for i:=from; i<=to; i++ {
    if i%2 == 0 {
      result += i*i
    }    
  }
  ch <- result
}

package main
import "fmt"

func evenSum(from, to int, ch chan int) {
    result := 0
    for i:=from; i<=to; i++ {
        if i%2 == 0 {
            result += i
        }    
    }
    ch <- result
}
func squareSum(from, to int, ch chan int) {
    result := 0
    for i:=from; i<=to; i++ {
        if i%2 == 0 {
            result += i*i
        }    
    }
    ch <- result
}

func main() {
    evenCh := make(chan int)
    sqCh := make(chan int)

    // 开启两个goruntine
    go evenSum(0, 100, evenCh)
    go squareSum(0, 100, sqCh)

    // 从管道中获取数据相加
    fmt.Println(<-evenCh + <- sqCh)
}

